import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/BDM.scaBLLhv.js";import{_ as o,a as r,b as i,c as s,d as n}from"./chunks/M-SS-LimiTTer.Bke--kwa.js";import{_ as l,o as d,c as p,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const S=JSON.parse('{"title":"Start sensor","description":"","frontmatter":{},"headers":[],"relativePath":"use/startsensor.md","filePath":"use/startsensor.md"}'),m={name:"use/startsensor.md"};function h(u,e,g,b,y,f){return d(),p("div",null,[...e[0]||(e[0]=[c('<p>Starting a sensor in xDrip has very different functions depending on the sensor itself.</p><h3 id="g6-and-1" tabindex="-1">G6 and 1 <a class="header-anchor" href="#g6-and-1" aria-label="Permalink to &quot;G6 and 1&quot;">​</a></h3><p>Reference documentation is <a href="https://navid200.github.io/xDrip/docs/Proper-connectivity.html" target="_blank" rel="noreferrer">here</a>.</p><h3 id="g7-and-1" tabindex="-1">G7 and 1+ <a class="header-anchor" href="#g7-and-1" aria-label="Permalink to &quot;G7 and 1+&quot;">​</a></h3><p>The sensor will start automatically at the time it is inserted. You don&#39;t need to start it in xDrip.</p><br><h3 id="libre" tabindex="-1">Libre <a class="header-anchor" href="#libre" aria-label="Permalink to &quot;Libre&quot;">​</a></h3><p>Note - this section does NOT apply to Libre 2/2+ (EU) connecting to xDrip without a bridge. For these, see the instructions for <a href="./../install/libre2.html#starting-libre-2-sensors">Libre 2 Direct</a></p><p>xDrip is not able to start a Libre sensor, nor is it able to stop one (actually you can&#39;t stop this sensor: if it doesn&#39;t fail it will run its useful lifetime and stop by itself after 14 days and 12 hours; Libre 3 sensors run for 15 days).</p><p>In order to start your sensor you need to use the vendor reader or app; some other third party apps like Glimp-S and eDropletNFC can start the Libre 1 sensor. Juggluco can start Libre 2 and 3 sensors.</p><p>xDrip sensor start is only used to track lifetime and make sure calibrations are updated. This operation is necessary and recommended each time you replace your sensor.</p><br><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Start sensor</p></div><p>Confirm START SENSOR</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;">Start New Sensor</p><p>Do not hit start sensor unless the sensor is already embedded and the transmitter is connected</p><p>    <span style="background-color:grey;color:white;align:center;">  START SENSOR </span></p></div><p>If you inserted the sensor today (i.e. not started or recently started), answer YES, TODAY</p><div class="admonition xdripitem"><p class="admonition-title">Did you insert it today?</p><p>We need to know when the sensor was inserted to improve calculation accuracy.</p><p><span style="color:cyan;float:right;">NOT TODAY  YES TODAY </span></p></div><p>If you answered today, select the hour you physically started the sensor by dragging the blue pointer to the correct time. With 12-hour display, tap <code>am</code> or <code>pm</code>. With 24-hour display drop the correct hour either on the inner or outer ring for the correct hour. Tap OK.</p><img src="'+o+'" style="zoom:75%;"><p>Drag the minutes blue pointer to the correct time and tap <code>OK</code>.</p><img src="'+r+'" style="zoom:75%;"><p>The newly started sensor will continue its warm-up if started less than one hour ago.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p><strong>Even if xDrip will attempt to read a sensor during its warm-up phase, values can range from unreliable to inconsistent and should not be used.</strong></p></div><img src="'+i+'" style="zoom:70%;"><p>If you&#39;re using <a href="./OOP.html#oop1">OOP1</a> or <a href="./OOP.html#oop2">OOP2</a> without calibration, BG will start displaying immediately without the need for the initial calibration.</p><p>If you&#39;re using an already started sensor you will have a calibration request within 15 minutes.</p><p>If you see a purple arrow you might have made a mistake in the date and time the sensor was started as BG data is available but won&#39;t display during the 1 hour warm-up.</p><img src="'+s+'" style="zoom:70%;"><br><p>xDrip will now wait for readings and update the progress. Stay on this screen. Every reading is done 5 minutes apart so it should take less than 20 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Collecting Initial Readings</p><p> ✔ Data Collector Running<br>  ⧖ Receiving Data from MiaoMiao Collector<br>   Received Some Recent Data<br>   Received Enough Good Data to Calibrate<br>  <em><strong>No data received yet</strong></em></p></div><p>If the data source shows LimiTTer and you&#39;re not using an actual <a href="https://github.com/JoernL/LimiTTer" target="_blank" rel="noreferrer">LimiTTer</a>, your bridge device is not connected correctly.</p><img src="'+n+'" style="zoom:70%;"><p>The indication <em><strong>No data received yet</strong></em> will change to <em><strong>Need 3 recent readings</strong></em>. If no data is received, <a href="./../install/libreBT.html#bridge-settings">check your parameters</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Collecting Initial Readings</p><p> ✔ Data Collector Running<br>  ✔ Receiving Data from MiaoMiao Collector<br>  ✔ Received Some Recent Data<br>  ⧖ Received Enough Good Data to Calibrate<br>  <em><strong>Need 3 recent readings, got only 1 so far</strong></em><br>  Next reading expected in 1 minute</p></div><p>When enough readings are received, the calibration request will display. More about calibration <a href="./../calibrate/101.html">here</a>.</p><p>If your BG is within normal range (recommended in the lower normal range for a new sensor) and has been stable for the last 10 minutes, with no carbs or insulin active, you can calibrate.</p><p>If your BG is quickly varying or not within normal range, it is not recommended to calibrate now.</p><div class="admonition xdrip"><p class="admonition-title">Calibrate Sensor?</p><p>We have some readings!<br> Next we need the first calibration blood test.<br> Ready to calibrate now?</p></div><p>Two readings may be required for the first calibration; you can use only one if you&#39;re sure it&#39;s valid. Just enter the same value twice. You can set one value as default <a href="./../calibrate/advancedcal.html#calibrations">disabling double calibration</a>.</p><p>Your BG should start displaying on the main graph.</p><br><h3 id="followers-and-companion-apps" tabindex="-1">Followers and companion apps <a class="header-anchor" href="#followers-and-companion-apps" aria-label="Permalink to &quot;Followers and companion apps&quot;">​</a></h3><p>It is sometimes necessary to &quot;start&quot; a sensor session in xDrip to get readings.</p><p>Starting or stopping a sensor in xDrip, when using a follower or companion source doesn&#39;t have any impact on the sensor.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>The only exception is <a href="./sync.html#accept-followers-actions">xDrip Sync follower that might transmit the Start or Stop command to the actual sensor if it is directly connected to xDrip acting as master</a>.<br> Do not use Start and Stop sensor with xDrip Sync follower unless you know the person with the master xDrip phone will know what to do with a stopped sensor!</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Start sensor</p></div><p>Confirm START SENSOR</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;">Start New Sensor</p><p>Do not hit start sensor unless the sensor is already embedded and the transmitter is connected</p><p>    <span style="background-color:grey;color:white;align:center;">  START SENSOR </span></p></div><p>Answer NOT TODAY</p><div class="admonition xdripitem"><p class="admonition-title">Did you insert it today?</p><p>We need to know when the sensor was inserted to improve calculation accuracy.</p><p><span style="color:cyan;float:right;">NOT TODAY  YES TODAY </span></p></div><p>xDrip should pick up readings with the next measurement.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',54)])])}const T=l(m,[["render",h]]);export{S as __pageData,T as default};
